import type { Page } from '@playwright/test';

export async function openAddOwnerForm(page: Page) {
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Add New" }).click();
}

export async function fillOwnerForm(page: Page, firstName: string, lastName: string, address: string, city: string, telephone: string) {
    await page.locator("#firstName").fill(firstName);
    await page.locator("#lastName").fill(lastName);
    await page.locator("#address").fill(address);
    await page.locator("#city").fill(city);
    await page.locator("#telephone").fill(telephone);
}

export async function submitAddOwnerForm(page: Page, responseUrlPattern: string) {
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse(responseUrlPattern);
    await page.getByRole("button", { name: "Add Owner" }).click();
    return await responsePromise;
}

export async function openOwnersList(page: Page) {
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
}

export async function openOwnerEditForm(page: Page) {
    await page.getByRole("button", { name: "Edit Owner" }).click();
}
